  if not values then
   values={colors={},floats={}}
   for _,key in ipairs(colorKeys)do if m:HasProperty(key)then values.colors[key]=m:GetColor(key)end end
   for _,key in ipairs(floatKeys)do if m:HasProperty(key)then values.floats[key]=m:GetFloat(key)end end
   e.blockValues=values
  end
