 if root==nil or not root.activeInHierarchy then root=U.GameObject.Find(job.name)end
 if root==nil then return false,'ROOT_NOT_LOADED'end;job.root=root;holdGate(job.name,root)
 local record=tracked[job.name]
 if record and record.root==root and record.complete and not job.force then return true end
