   local root=(job and job.root)or(record and record.root)or U.GameObject.Find(name)
   if root then holdGate(name,root);g=gates[name]end
   if g and not g.failedOpen then
    if record and record.complete and not job and U.Time.frameCount>(readyFrames[name]or -1)then
     local ok,ready=pcall(appearanceReady,record)
     if ok and ready then releaseGate(name)else enqueue(name,root,true)end
